import eel from ultralytics import YOLO from PIL import Image import cv2 import base64 import io
# Load model model = YOLO("models/best.pt")
# Dictionary of recommendations by disease recommendations = { "Apple___Black_rot": "Remove infected leaves and apply fungicide.", "Apple___Cedar_apple_rust": "Apply preventive fungicide and control humidity.", "Apple___healthy": "Maintain adequate watering and balanced fertilization.", "Cherry___Powdery_mildew": "Use fungicide and improve ventilation.", "Cherry___healthy": "Maintain regular pruning and fertilization.", "Corn___Cercospora_leaf_spot Gray_leaf_spot": "Rotate crops and apply fungicide.", "Corn___Common_rust": "Use resistant varieties and fungicide.", "Corn___Northern_Leaf_Blight": "Remove crop residues and apply fungicide.", "Corn___healthy": "Maintain balanced fertilization and watering.", "Potato___Early_blight": "Apply fungicide and control humidity.", "Potato___Late_blight": "Avoid excess water and apply fungicide.", "Potato___healthy": "Maintain crop rotation and fertilization.", "Strawberry___Leaf_scorch": "Avoid excess direct sun and improve watering.", "Strawberry___healthy": "Maintain fertilization and adequate watering." }
@eel.expose def process_image(data_url): header, encoded = data_url.split(",", 1) data = base64.b64decode(encoded) img = Image.open(io.BytesIO(data)) img_path = "web/temp.jpg" img.save(img_path) results = model.predict(source=img_path, save=True) clase = results[0].names[int(results[0].boxes.cls[0])] conf = results[0].boxes.conf[0].item() rec = recommendations.get(clase, 'Not available') return {'image': data_url, 'class': clase, 'confidence': f"{conf:.2f}", 'recommendation': rec}
eel.init('web') eel.start('index.html', size=(800, 600))
